INSERT INTO `customer_reviews` (`id`, `reviewer_name`, `rating`, `food_rating`, `service_rating`, `atmosphere_rating`, `comment`, `source`, `reviewed_ago`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (1, 'Riddhi Ghaghada', 5, 5, 5, 5, 'All the food is extremely delicious. Among them, UMBADIYU tasted amazing and is truly one of the best in all of Ahmedabad. You should definitely try it..😋', 'google', '7 months ago', 1, 1, 1, '2026-09-07 15:37:10', '2026-09-07 15:37:10');
INSERT INTO `customer_reviews` (`id`, `reviewer_name`, `rating`, `food_rating`, `service_rating`, `atmosphere_rating`, `comment`, `source`, `reviewed_ago`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (2, 'Fresha Patel', 5, 5, 5, 5, 'Absolutely amazing Umbadiyu! Not spicy at all, yet full of authentic flavor. Truly delicious and a must-visit place', 'google', '8 months ago', 1, 1, 2, '2026-09-07 15:37:10', '2026-09-07 15:37:10');
INSERT INTO `customer_reviews` (`id`, `reviewer_name`, `rating`, `food_rating`, `service_rating`, `atmosphere_rating`, `comment`, `source`, `reviewed_ago`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (3, 'Urvil Sarvasva', 5, 5, 5, 5, 'Excellent umbaiyu. Glad we now have umbadiyu place in gota. They serve it with chutneys which is great as eating umbadiyu alone is not great to swallow. Chutneys with umbadiyu are definately worth it.', 'google', '9 months ago', 1, 1, 3, '2026-09-07 15:37:10', '2026-09-07 15:37:10');
INSERT INTO `customer_reviews` (`id`, `reviewer_name`, `rating`, `food_rating`, `service_rating`, `atmosphere_rating`, `comment`, `source`, `reviewed_ago`, `is_featured`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (4, 'Ghanshyam Solanki', 5, 5, 4, 4, 'Delicious food, mainly umbadiyu is testy.', 'google', '7 months ago', 1, 1, 4, '2026-09-07 15:37:10', '2026-09-07 15:37:10');
